function changeSlide(e){clearTimeout(slideTimer),showSlides(slideIndex+=e),startAutoSlide()}function currentSlide(e){clearTimeout(slideTimer),showSlides(slideIndex=e),startAutoSlide()}function showSlides(e){let l,s=document.getElementsByClassName("slide"),i=document.getElementsByClassName("dot");for(e>s.length&&(slideIndex=1),e<1&&(slideIndex=s.length),l=0;l<s.length;l++)s[l].style.display="none";for(l=0;l<i.length;l++)i[l].className=i[l].className.replace(" active","");s[slideIndex-1].style.display="block",i[slideIndex-1].className+=" active"}function startAutoSlide(){slideTimer=setTimeout(function(){slideIndex++,showSlides(slideIndex),startAutoSlide()},4e3)}let slideTimer,slideIndex=1;showSlides(slideIndex),startAutoSlide();